const state={pendingAction:null,mineOnly:false,orders:[],order:null,tab:'persons',selected:new Set(),person:null,uploading:false,progress:null,query:'',view:'photos',photoFilter:'all',shootId:undefined,clientLink:null,confirmRun:null};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<img src="/static/assets/${name}.svg" alt="">`;
const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n)+' ₽';
const count=(n,one,few,many)=>`${n} ${n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many}`;
const photoLabel=n=>count(n,'фотография','фотографии','фотографий');
const statuses={pending:'В очереди',processing:'Обработка',no_face:'Лицо не найдено',multiple_faces:'Несколько лиц',small_face:'Лицо слишком маленькое',error:'Ошибка обработки',ready:'Готово'};
const STAGES=[['new','Загрузить фото','#7712b3','#fff','Классы, где съёмка прошла, а фотографии ещё не загружены.'],['photos','Проверить фото','#4d6ff0','#fff','Проверьте группы портретов и отправьте классу анкеты.'],['forms','Собрать анкеты','#50b7f1','#0b2a3d','Класс выбирает портреты и заполняет подписи. Когда анкеты готовы, создайте макет.'],['layout','Сверстать макет','#28cec5','#063a37','Проверьте собранный макет и отправьте его классу на согласование.'],['approval','Согласовать макет','#f29b38','#3d2200','Макет у класса. После согласования отправьте заказ в печать.'],['print','Напечатать','#e2458a','#fff','Заказы в типографии. Отметьте, когда альбомы переданы в доставку.'],['delivery','Доставить','#3aa655','#fff','Альбомы едут к классу. После выдачи перенесите заказ в архив.'],['archive','Архив','#8a8b85','#fff','Завершённые заказы.']];
const stageOf=key=>STAGES.find(s=>s[0]===key)||STAGES[0];
const stageLabel=key=>stageOf(key)[1];
const daysIn=o=>Math.max(0,Math.floor((Date.now()-Date.parse(o.stage_at||o.created_at))/864e5));
const isMine=st=>st.kind==='todo'||st.kind==='done';
const tone=(o,st)=>isMine(st)?'mine':st.kind==='waiting'&&o.stage!=='archive'&&daysIn(o)>=10?'stale':st.kind;
const LEGACY_STAGES={planned:'new',scheduled:'new',upload:'photos'};
const withStage=o=>{if(!STAGES.some(s=>s[0]===o.stage))o.stage=LEGACY_STAGES[o.stage]||'new';return o;};
const fmtDate=d=>String(d||'').split('-').reverse().join('.');
let toastTimer,pollTimer,routeVersion=0,groupsSig='';
async function api(path,options={}){const r=await fetch('/api'+path,options);let value=await r.json();if(!r.ok)throw Error(typeof value.detail==='string'?value.detail:'Проверьте заполнение полей');return value;}
function json(method,body){return {method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)};}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function orderName(o){return `${o.school} / ${o.class_name}`;}
function personName(p,index){return p.name||`Персона ${String(index+1).padStart(2,'0')}`;}
function defaultGraduationYear(date=new Date()){return date.getFullYear()+(date.getMonth()>=8?1:0);}
function packageMeta(p){const s=p.summary||{},parts=[];if(s.spreads)parts.push(count(s.spreads,'разворот','разворота','разворотов'));if(s.page_size)parts.push(`${s.page_size[0]}×${s.page_size[1]}`);return parts.join(' · ');}
function packageCover(d,i){return `<span class="package-thumb cover-${i%3}"><span class="mini-book"><span><small>ALBUM FACTORY</small><strong>${esc(d.name)}</strong></span><span class="mini-art"><i></i><i></i><i></i></span></span></span>`;}
function packageRow(item){return item.package?`${packageCover(item.design,item.index)}<span class="package-text"><strong>${esc(item.package.name)}</strong><small>${esc([item.design.name,packageMeta(item.package)].filter(Boolean).join(' · '))}</small></span><b class="package-price">${money(item.package.price)}</b>`:`<span class="package-thumb later">${svgIcon(item.later?'clock':'layout',18)}</span><span class="package-text"><strong>${item.later?'Выбрать позже':'Выберите комплектацию'}</strong><small>${item.later?'Цену возьмём из комплектации при создании макета':'Цена альбома берётся из комплектации'}</small></span>`;}
function packagePicker(designs,selected='',optional=true){const items=designs.flatMap((design,index)=>design.packages.map(p=>({design,index,package:p}))),current=items.find(x=>x.package.template_id===selected),empty={later:optional};const option=(item,value)=>`<button type="button" role="option" class="package-item" data-package="${esc(value)}" aria-selected="${value===(current?selected:'')}">${packageRow(item)}</button>`;const list=(optional?option(empty,''):'')+designs.map((d,i)=>d.packages.length?`<div class="package-group" role="group" aria-label="${esc(d.name)}"><h3>${esc(d.name)}</h3>${d.packages.map(p=>option({design:d,index:i,package:p},p.template_id)).join('')}</div>`:'').join('');return `<div class="package-select"><input type="hidden" name="master_template_id" value="${esc(current?selected:'')}"><button type="button" class="package-trigger" aria-haspopup="listbox" aria-expanded="false">${packageRow(current||empty)}${svgIcon('chevron',18)}</button><div class="package-list" role="listbox" hidden>${list||''}${items.length?'':`<p class="package-empty muted">Пока нет комплектаций. Создайте дизайн в разделе <a href="#masters">«Мастер-макеты»</a>.</p>`}</div></div>`;}
function placePackageList(root){const list=root.querySelector('.package-list'),box=root.querySelector('.package-trigger').getBoundingClientRect(),below=innerHeight-box.bottom-16,above=box.top-16,up=below<280&&above>below,max=Math.min(360,up?above:below);list.style.left=box.left+'px';list.style.width=box.width+'px';list.style.maxHeight=max+'px';list.style.top=up?'':box.bottom+6+'px';list.style.bottom=up?innerHeight-box.top+6+'px':'';}
function togglePackages(root,open){const list=root.querySelector('.package-list'),trigger=root.querySelector('.package-trigger');list.hidden=!open;trigger.setAttribute('aria-expanded',String(open));root.classList.toggle('open',open);if(open){placePackageList(root);(list.querySelector('[aria-selected="true"]')||list.querySelector('.package-item'))?.focus();}}
function choosePackage(item){const root=item.closest('.package-select');root.querySelector('input').value=item.dataset.package;root.querySelectorAll('.package-item').forEach(x=>x.setAttribute('aria-selected',String(x===item)));root.querySelector('.package-trigger').innerHTML=item.innerHTML+svgIcon('chevron',18);togglePackages(root,false);root.querySelector('.package-trigger').focus();root.querySelector('input').dispatchEvent(new Event('change',{bubbles:true}));}
document.addEventListener('click',e=>{const trigger=e.target.closest('.package-trigger'),item=e.target.closest('.package-item');if(trigger){const root=trigger.closest('.package-select');togglePackages(root,root.querySelector('.package-list').hidden);}else if(item)choosePackage(item);});
document.addEventListener('pointerdown',e=>{document.querySelectorAll('.package-select.open').forEach(root=>{if(!root.contains(e.target))togglePackages(root,false);});},true);
document.addEventListener('keydown',e=>{const root=e.target.closest?.('.package-select');if(!root)return;const open=root.classList.contains('open');if(e.key==='Escape'&&open){e.preventDefault();e.stopPropagation();togglePackages(root,false);root.querySelector('.package-trigger').focus();return;}if(!['ArrowDown','ArrowUp'].includes(e.key))return;e.preventDefault();if(!open){togglePackages(root,true);return;}const items=[...root.querySelectorAll('.package-item')],at=items.indexOf(document.activeElement);items[(at+(e.key==='ArrowDown'?1:-1)+items.length)%items.length]?.focus();},true);
document.addEventListener('scroll',e=>{document.querySelectorAll('.package-select.open').forEach(root=>{if(!root.contains(e.target))togglePackages(root,false);});},true);
addEventListener('resize',()=>document.querySelectorAll('.package-select.open').forEach(placePackageList));
async function schoolChoices(){const saved=await api('/schools'),known=new Set(saved.map(s=>searchKey(s.name)));const legacy=[...new Set(state.orders.map(o=>o.school).filter(Boolean))].filter(n=>!known.has(searchKey(n))).map(name=>({id:'',name}));return [...saved,...legacy].sort((a,b)=>a.name.localeCompare(b.name,'ru'));}
function schoolPicker(root,list,current=null){let chosen=current,active=0;const listId=root.id+'-options';const pick=async o=>{const error=root.querySelector('.school-error');try{if(!o.id){const r=await api('/schools',json('POST',{name:o.name}));o={id:r.id,name:r.name};list=[...list.filter(s=>searchKey(s.name)!==searchKey(o.name)),o].sort((a,b)=>a.name.localeCompare(b.name,'ru'));}chosen=o;draw();}catch(e){if(error)error.textContent=e.message;}};const draw=()=>{if(chosen){root.innerHTML=`<div class="school-chosen">${svgIcon('school',18)}<strong>${esc(chosen.name)}</strong><button type="button" class="link-button">Изменить</button><input type="hidden" name="school_id" value="${esc(chosen.id)}"><input type="hidden" name="school" value="${esc(chosen.name)}"></div>`;root.querySelector('button').onclick=()=>{chosen=null;draw();root.querySelector('input').focus();};return;}root.innerHTML=`<div class="school-search">${svgIcon('search',16)}<input type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${listId}" aria-label="Школа" placeholder="Найдите или создайте школу" autocomplete="off" maxlength="100"></div><ul class="school-options" id="${listId}" role="listbox" hidden></ul><p class="school-error error" role="alert"></p>`;const input=root.querySelector('input'),ul=root.querySelector('ul');const options=()=>{const text=input.value.trim().replace(/\s+/g,' '),q=searchKey(text),hits=list.filter(s=>!q||searchKey(s.name).includes(q));return q&&!list.some(s=>searchKey(s.name)===q)?[...hits,{id:'',name:text,create:true}]:hits;};const drawList=()=>{const opts=options();active=Math.max(0,Math.min(active,opts.length-1));ul.innerHTML=opts.map((o,i)=>`<li role="option" id="${listId}-${i}" data-i="${i}" class="${i===active?'active':''}${o.create?' create':''}" aria-selected="${i===active}">${o.create?`${svgIcon('plus',16)}<span>Создать школу «${esc(o.name)}»</span>`:`${svgIcon('school',16)}<span>${esc(o.name)}</span>`}</li>`).join('')||'<li class="empty">Школ пока нет — введите название, чтобы создать первую</li>';input.setAttribute('aria-activedescendant',opts.length?`${listId}-${active}`:'');ul.onmousedown=e=>e.preventDefault();ul.onclick=e=>{const li=e.target.closest('[data-i]');if(li)pick(opts[+li.dataset.i]);};};const open=()=>{ul.hidden=false;input.setAttribute('aria-expanded','true');drawList();};input.onclick=open;input.oninput=()=>{active=0;root.querySelector('.school-error').textContent='';open();};input.onblur=()=>{ul.hidden=true;input.setAttribute('aria-expanded','false');};input.onkeydown=e=>{const opts=options();if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();ul.hidden=false;active=(active+(e.key==='ArrowDown'?1:-1)+opts.length)%Math.max(1,opts.length);drawList();ul.querySelector('.active')?.scrollIntoView({block:'nearest'});}else if(e.key==='Enter'){e.preventDefault();if(!ul.hidden&&opts[active])pick(opts[active]);}else if(e.key==='Escape'&&!ul.hidden){e.preventDefault();e.stopPropagation();input.blur();}};};draw();return {get value(){return chosen;}};}
let orderSchool=null;
async function openNew(){$('#order-form').reset();$('#graduation-year').value=defaultGraduationYear();$('#form-error').textContent='';const packages=$('#order-packages'),school=$('#order-school');packages.innerHTML='<p class="muted small">Загружаем комплектации…</p>';school.innerHTML='<p class="muted small">Загружаем школы…</p>';orderSchool=null;$('#order-dialog').showModal();const [schools,designs]=await Promise.allSettled([schoolChoices(),api('/designs')]);if(!$('#order-dialog').open)return;orderSchool=schoolPicker(school,schools.value||[]);if(schools.status==='rejected')$('#form-error').textContent='Не удалось загрузить школы. Новую школу можно создать здесь же.';packages.innerHTML=designs.status==='fulfilled'?packagePicker(designs.value):'<p class="error">Не удалось загрузить мастер-макеты. Можно создать заказ и выбрать комплектацию позже.</p>'+packagePicker([]);school.querySelector('input')?.focus();}
async function chooseOrderMaster(){const id=state.order.id;$('#action-content').innerHTML='<div class="dialog-heading"><h2>Создать макет</h2><button class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><p class="muted">Загружаем мастер-макеты…</p>';$('#action-dialog').showModal();try{const designs=await api('/designs');if(!$('#action-dialog').open||state.order?.id!==id)return;const c=state.order.client_progress,left=c?.enabled?c.total-c.completed:0;$('#action-dialog').classList.add('wide-dialog');$('#action-content').innerHTML=`<form id="layout-master-form"><div class="dialog-heading"><h2>Создать макет</h2><button type="button" class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><fieldset class="package-field"><legend>Дизайн и комплектация</legend>${packagePicker(designs,state.order.master_template_id,false)}</fieldset>${state.order.stage==='layout'||state.view==='layout'?'<p class="muted small">При выборе другой комплектации макет будет собран заново, без правок предыдущего макета.</p>':''}${left>0?`<p class="muted">Ещё не заполнены ${left} анкет. Для них возьмём первый готовый портрет.</p>`:''}<p id="layout-master-error" class="error" role="alert"></p><button type="submit" class="primary wide">Создать макет</button></form>`;$('#layout-master-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');if(!e.target.master_template_id.value){$('#layout-master-error').textContent='Выберите комплектацию.';return;}b.disabled=true;try{await api('/orders/'+id+'/layout',json('POST',Object.fromEntries(new FormData(e.target))));$('#action-dialog').close();if(location.hash===`#order/${id}/layout`)await route();else location.hash=`order/${id}/layout`;toast('Макет создан');}catch(error){$('#layout-master-error').textContent=error.message;}finally{b.disabled=false;}};}catch(error){$('#action-content').innerHTML=`<p class="error">${esc(error.message)}</p><button class="secondary" data-close="action-dialog">Закрыть</button>`;}}

// Dashboard and order registry share the same status model as the stage queues.
const orderFilters={query:'',school:'',className:'',stage:'',scope:'all',attention:false};
const searchKey=value=>String(value||'').toLocaleLowerCase('ru').replace(/ё/g,'е').replace(/[\s«»"№/·-]/g,'');
function registryOrders(){const f=orderFilters,q=searchKey(f.query);return state.orders.filter(o=>(!q||searchKey([o.school,o.class_name,o.customer_name,o.customer_contact].join(' ')).includes(q))&&(!f.school||o.school===f.school)&&(!f.className||searchKey(o.class_name)===searchKey(f.className))&&(!f.stage||o.stage===f.stage)&&((f.scope==='archive'?o.stage==='archive':f.scope==='waiting'?['forms','approval'].includes(o.stage)&&cardStatus(o).kind==='waiting':o.stage!=='archive'))&&(!f.attention||isMine(cardStatus(o)))).sort((a,b)=>isMine(cardStatus(b))-isMine(cardStatus(a))||daysIn(b)-daysIn(a));}
function homePage(){ $('#main').innerHTML=`<div class="page dashboard"><div class="dashboard-heading"><div><h1>Главная</h1></div><button class="primary" data-action="new-order">＋ Создать заказ</button></div><form class="dashboard-search" id="home-search">${svgIcon('search',20)}<input type="search" aria-label="Найти заказ" placeholder="Найти заказ по школе, классу или заказчику"><button type="submit">Найти заказ →</button></form><div id="dashboard-content"></div><a class="classic-link" href="#home-classic">Предыдущая версия главной ↗</a></div>`;$('#home-search').onsubmit=e=>{e.preventDefault();location.hash='orders?q='+encodeURIComponent($('#home-search input').value);};drawHome();}
function drawHome(){const el=$('#dashboard-content');if(!el)return;const active=state.orders.filter(o=>o.stage!=='archive'),tasks=active.filter(o=>isMine(cardStatus(o))).sort((a,b)=>(cardStatus(b).icon==='alert')-(cardStatus(a).icon==='alert')||daysIn(b)-daysIn(a)),waiting=active.filter(o=>cardStatus(o).kind==='waiting'),printed=active.filter(o=>o.stage==='print');el.innerHTML=`<div class="dashboard-metrics">${[['В работе',active.length,'scope=active'],['Требуют действий',tasks.length,'attention=1'],['Ждём класс',waiting.filter(o=>['forms','approval'].includes(o.stage)).length,'scope=waiting'],['В печати',printed.length,'stage=print']].map(([label,n,filter],i)=>`<a href="#orders?${filter}" class="${i===1?'metric-attention':''}"><span>${label} ↗</span><strong>${n}</strong></a>`).join('')}</div><section class="attention-panel"><div class="dashboard-section-head"><div><h2>Требуют внимания <span>${tasks.length}</span></h2></div><a href="#orders?attention=1">Все задачи →</a></div>${tasks.length?tasks.slice(0,6).map(o=>{const st=cardStatus(o);return `<div class="attention-row"><span class="attention-icon">${svgIcon(st.icon,20)}</span><a class="attention-info" href="#order/${o.id}/${st.tab}"><strong>${esc(o.school)} · ${esc(o.class_name)}</strong><span>${esc(st.text)}</span></a><span class="attention-age">На этапе ${count(daysIn(o),'день','дня','дней')}</span>${actionButton(o,st)}</div>`;}).join(''):`<div class="dashboard-empty"><h3>${state.orders.length?'Всё под контролем':'Начните с первого заказа'}</h3><p>${state.orders.length?'Сейчас нет заказов, требующих вашего действия.':'Добавьте школу и класс, затем загрузите фотографии.'}</p>${!state.orders.length?'<button class="primary" data-action="new-order">Создать заказ</button>':''}</div>`}</section><section class="dashboard-process"><div class="dashboard-section-head"><div><h2>Заказы по этапам</h2><p class="muted">Общая картина производства</p></div><a href="#orders">Все заказы →</a></div><div class="stage-overview">${STAGES.filter(([k])=>k!=='archive').map(([k,label])=>{const n=active.filter(o=>o.stage===k).length;return `<a href="#orders?stage=${k}" class="${n?'has-orders':''}">${svgIcon(STAGE_ICONS[k],18)}<span>${label}</span><strong>${n}</strong></a>`;}).join('')}</div></section>`;}
let registryView;
function ordersView(){if(registryView)return registryView;try{return localStorage.getItem('ordersView')==='grid'?'grid':'list';}catch{return 'list';}}
function ordersPage(params=new URLSearchParams()){if(params.size){Object.assign(orderFilters,{query:params.get('q')||'',school:params.get('school')||'',className:params.get('class')||'',stage:params.get('stage')||'',scope:params.get('scope')||'all',attention:params.get('attention')==='1'});}const f=orderFilters,view=ordersView();$('#main').innerHTML=`<div class="page registry"><div class="queue-head"><div><h1>Все заказы</h1><p class="muted">Школы, классы и состояние каждого заказа</p></div><div class="queue-tools"><label class="queue-search ${f.query?'open':''}"><button type="button" id="orders-search-toggle" title="Поиск" aria-label="Поиск">${svgIcon('search',16)}</button><input id="orders-search" type="search" aria-label="Поиск заказа" placeholder="Школа, класс, заказчик" value="${esc(f.query)}"></label><div class="segmented" role="group" aria-label="Вид заказов"><button data-orders-view="list" aria-label="Список" title="Список" aria-pressed="${view==='list'}">${svgIcon('list',16)}</button><button data-orders-view="grid" aria-label="Плитка" title="Плитка" aria-pressed="${view==='grid'}">${svgIcon('grid',16)}</button></div><button class="primary" data-action="new-order">＋ Создать заказ</button></div></div><div class="registry-scopes">${[['all','Все'],['active','В работе'],['waiting','Ждём класс'],['archive','Архив']].map(([k,label])=>`<button data-order-scope="${k}" aria-pressed="${f.scope===k}">${label}</button>`).join('')}</div><div class="registry-filters"><label>Школа<select id="filter-school"><option value="">Все школы</option>${[...new Set(state.orders.map(o=>o.school))].sort((a,b)=>a.localeCompare(b,'ru',{numeric:true})).map(v=>`<option ${f.school===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label><label>Класс<select id="filter-class"><option value="">Все классы</option>${[...new Map(state.orders.map(o=>[searchKey(o.class_name),o.class_name])).values()].sort((a,b)=>a.localeCompare(b,'ru',{numeric:true})).map(v=>`<option ${searchKey(f.className)===searchKey(v)?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select></label><label>Этап<select id="filter-stage"><option value="">Все этапы</option>${STAGES.map(([k,label])=>`<option value="${k}" ${f.stage===k?'selected':''}>${label}</option>`).join('')}</select></label><label class="registry-attention"><input type="checkbox" id="filter-attention" ${f.attention?'checked':''}> Требуют действий</label><button class="text-button" id="orders-reset">Сбросить</button></div><div id="orders-summary" class="registry-summary" aria-live="polite"></div><div id="orders-items"></div></div>`;const input=$('#orders-search');$('#orders-search-toggle').onclick=()=>{input.parentElement.classList.add('open');input.focus();};input.oninput=()=>{f.query=input.value;drawOrders();};input.onblur=()=>{if(!input.value)input.parentElement.classList.remove('open');};input.onkeydown=e=>{if(e.key==='Escape'){input.value='';f.query='';input.blur();drawOrders();}};for(const [id,key] of [['school','school'],['class','className'],['stage','stage']])$('#filter-'+id).onchange=e=>{f[key]=e.target.value;drawOrders();};$('#filter-attention').onchange=e=>{f.attention=e.target.checked;drawOrders();};$('#orders-reset').onclick=()=>{Object.assign(f,{query:'',school:'',className:'',stage:'',scope:'all',attention:false});history.replaceState(null,'','#orders');ordersPage();};document.querySelectorAll('[data-order-scope]').forEach(b=>b.onclick=()=>{f.scope=b.dataset.orderScope;document.querySelectorAll('[data-order-scope]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawOrders();});document.querySelectorAll('[data-orders-view]').forEach(b=>b.onclick=()=>{registryView=b.dataset.ordersView;try{localStorage.setItem('ordersView',registryView);}catch{}document.querySelectorAll('[data-orders-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawOrders();});drawOrders();}
function drawOrders(){const el=$('#orders-items');if(!el)return;const params=new URLSearchParams();for(const [key,value] of Object.entries({q:orderFilters.query,school:orderFilters.school,class:orderFilters.className,stage:orderFilters.stage,scope:orderFilters.scope==='all'?'':orderFilters.scope,attention:orderFilters.attention?'1':''}))if(value)params.set(key,value);history.replaceState(null,'','#orders'+(params.size?'?'+params:''));const rows=registryOrders(),view=ordersView();$('#orders-summary').textContent=`${count(rows.length,'заказ','заказа','заказов')} · ${count(rows.reduce((n,o)=>n+(o.copies||0),0),'альбом','альбома','альбомов')} · Сумма заказов ${money(rows.reduce((n,o)=>n+(o.copies||0)*(o.price||0),0))}`;el.className=view==='grid'?'registry-grid':'registry-table-wrap';if(!rows.length){el.innerHTML=`<div class="empty-state"><h3>${state.orders.length?'Заказы не найдены':'Заказов пока нет'}</h3><p>${state.orders.length?'Измените условия поиска или сбросьте фильтры.':'Создайте первый заказ, чтобы начать работу.'}</p></div>`;return;}const stageBadge=o=>`<span class="registry-stage">${esc(stageLabel(o.stage))}</span>`;el.innerHTML=view==='grid'?rows.map(o=>{const st=cardStatus(o);return `<article class="registry-card"><a href="#order/${o.id}/${st.tab}" class="registry-card-link"><div class="registry-card-top">${svgIcon(STAGE_ICONS[o.stage],22)}${stageBadge(o)}</div><h2>${esc(o.school)}</h2><strong class="registry-class">${esc(o.class_name)}</strong><p class="registry-status">${esc(st.text)}</p>${st.progress?`<progress value="${st.progress[0]}" max="${st.progress[1]||1}" aria-label="Готовность анкет"></progress>`:''}<div class="registry-card-meta"><span>${count(o.copies||0,'альбом','альбома','альбомов')}</span><span>${daysIn(o)} дн. на этапе</span></div></a><div class="registry-card-bottom">${actionButton(o,st)||`<a class="secondary" href="#order/${o.id}/${st.tab}">Открыть заказ →</a>`}</div></article>`;}).join(''):`<table class="registry-table"><thead><tr><th>Школа / класс</th><th>Этап и состояние</th><th>Альбомов</th><th>На этапе</th><th><span class="muted">Следующий шаг</span></th></tr></thead><tbody>${rows.map(o=>{const st=cardStatus(o);return `<tr><td><a class="registry-order-link" href="#order/${o.id}/${st.tab}"><strong>${esc(o.school)}</strong><span>${esc(o.class_name)}</span></a></td><td>${stageBadge(o)}<small class="registry-status">${esc(st.text)}</small></td><td>${o.copies||0}</td><td class="registry-age">${count(daysIn(o),'день','дня','дней')}</td><td>${actionButton(o,st)||`<a class="registry-open" href="#order/${o.id}/${st.tab}">Открыть →</a>`}</td></tr>`;}).join('')}</tbody></table>`;}

function classicHomePage(){$('#main').innerHTML=`<div class="page home"><h1>Главная</h1><div id="home-top"></div><section class="process"><div class="process-head"><h2>Процесс</h2><div class="segmented" role="group" aria-label="Показать заказы"><button data-v2="filter-all" aria-pressed="${!state.mineOnly}">Все</button><button data-v2="filter-mine" aria-pressed="${state.mineOnly}">Ваш ход</button></div><label class="search"><input id="search" type="search" placeholder="Школа или класс" aria-label="Поиск заказа" value="${esc(state.query)}"></label></div><div id="board"></div><div class="legend"><span class="tone-mine">Ваш ход</span><span class="tone-working">Идёт работа</span><span class="tone-waiting">Ждём класс</span><span class="tone-stale">Ждёт дольше 10 дней</span></div></section></div>`;enableBoardDragging($('#board'));drawClassicHome();$('#search').oninput=e=>{state.query=e.target.value;drawBoard();};}
function enableBoardDragging(board){
  let startX=0,startScroll=0,pointerId=null,dragged=false,suppressClick=false;
  board.addEventListener('pointerdown',e=>{
    if(e.pointerType==='touch'||e.button!==0||board.scrollWidth<=board.clientWidth)return;
    pointerId=e.pointerId;startX=e.clientX;startScroll=board.scrollLeft;dragged=false;
  });
  board.addEventListener('pointermove',e=>{
    if(e.pointerId!==pointerId)return;
    if(!dragged&&Math.abs(e.clientX-startX)<6)return;
    if(!dragged){dragged=true;board.setPointerCapture(pointerId);board.classList.add('is-dragging');}
    board.scrollLeft=startScroll-(e.clientX-startX);
    e.preventDefault();
  });
  const finish=e=>{
    if(e.pointerId!==pointerId)return;
    if(dragged){suppressClick=true;setTimeout(()=>{suppressClick=false;},0);board.classList.remove('is-dragging');if(board.hasPointerCapture(pointerId))board.releasePointerCapture(pointerId);}
    pointerId=null;dragged=false;
  };
  board.addEventListener('pointerup',finish);
  board.addEventListener('pointercancel',finish);
  board.addEventListener('dragstart',e=>{if(pointerId!==null)e.preventDefault();});
  board.addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopPropagation();suppressClick=false;}},true);
}
function drawClassicHome(){const el=$('#home-top');if(!el)return;if(!state.orders.length){el.innerHTML=emptyOrders();$('.process').hidden=true;return;}$('.process').hidden=false;const tasks=state.orders.map(o=>[o,cardStatus(o)]).filter(([,st])=>isMine(st)&&st.action).sort((a,b)=>daysIn(b[0])-daysIn(a[0])),albums=state.orders.reduce((n,o)=>n+(o.copies||0),0),revenue=state.orders.reduce((n,o)=>n+(o.copies||0)*(o.price||0),0),done=state.orders.filter(o=>['print','delivery','archive'].includes(o.stage)).length;el.innerHTML=`<section class="home-top"><div class="tasks-card"><div class="tasks-head"><h2>Ваши задачи</h2><span>${tasks.length?count(tasks.length,'заказ ждёт','заказа ждут','заказов ждут')+' вас':'Сейчас всё идёт своим ходом'}</span></div><div class="tasks-list">${tasks.map(([o,st])=>`<div class="task-row"><a class="task-text" href="#order/${o.id}/${st.tab}"><strong>${esc(o.class_name)}</strong> <span>· ${esc(o.school)}</span><small>${esc(st.text)}${daysIn(o)?' · '+count(daysIn(o),'день','дня','дней'):''}</small></a>${actionButton(o,st)}</div>`).join('')||'<p class="muted tasks-empty">Новые задачи появятся, когда фотографии обработаются или класс заполнит анкеты.</p>'}</div></div><div class="report-card"><div class="report-head"><h2>Отчёт</h2><span>Все заказы</span></div><div class="report-stats"><div><span>Заказов</span><strong>${state.orders.length}</strong></div><div><span>Альбомов</span><strong>${albums}</strong></div><div><span>Выручка</span><strong>${money(revenue)}</strong></div></div><div class="report-progress"><div><span>Отправлено в печать</span><span>${done} из ${state.orders.length}</span></div><i><b style="width:${Math.round(done/state.orders.length*100)}%"></b></i></div></div></section>`;drawBoard();}
function drawBoard(){const el=$('#board');if(!el)return;const q=state.query.toLowerCase(),list=state.orders.filter(o=>orderName(o).toLowerCase().includes(q));el.innerHTML=STAGES.map(([k,l,color,ink])=>{const rows=list.filter(o=>o.stage===k);return rows.length?`<section class="board-col" style="--stage:${color};--stage-ink:${ink}"><a class="board-head" href="#stage/${k}"><span>${svgIcon(STAGE_ICONS[k],16)}${l}</span><small>${rows.length}</small></a><div class="board-rows">${rows.map(boardRow).join('')}</div></section>`:`<a class="board-strip" href="#stage/${k}" style="--stage:${color}" title="${l}"><span>${l}</span></a>`;}).join('');}
function boardRow(o){const st=cardStatus(o),t=tone(o,st),d=daysIn(o);return `<a class="board-row tone-${t} ${state.mineOnly&&t!=='mine'?'faded':''}" href="#order/${o.id}/${st.tab}"><i class="dot"></i><span><strong>${esc(o.class_name)} <em>· ${esc(o.school)}</em></strong><small>${esc(st.text)}${!isMine(st)&&d?' · '+d+' дн':''}</small>${st.progress?`<progress max="${st.progress[1]}" value="${st.progress[0]}"></progress>`:''}</span></a>`;}
// Queue rows: red only when something blocks the order, green when it can go on as is.
const queueState=(o,st)=>st.icon==='alert'||tone(o,st)==='stale'?'error':st.kind;
function actionButton(o,st,extra=''){const [act,label]=st.action||[];if(!act)return '';return act==='review'||act==='layout'?`<a class="secondary task-button ${extra}" href="#order/${o.id}/${st.tab}">${label} →</a>`:`<button class="secondary task-button ${extra}" data-card-action="${act}" data-id="${o.id}" data-tab="${st.tab}">${label} →</button>`;}
function queueView(){try{return localStorage.getItem('queueView')==='grid'?'grid':'list';}catch{return 'list';}}
function queueText(o,st){return `<span class="queue-text"><strong>${esc(o.school)} <em>· ${esc(o.class_name)}</em></strong><small>${esc(st.text)}</small>${st.progress?`<progress max="${st.progress[1]}" value="${st.progress[0]}"></progress>`:''}</span>`;}
function queueRow(o,st){return `<article class="queue-row state-${queueState(o,st)}"><a class="queue-main" href="#order/${o.id}/${st.tab}"><span class="queue-status">${svgIcon(st.icon,18)}</span>${queueText(o,st)}</a>${actionButton(o,st,st.kind==='done'?'is-ready':'')}</article>`;}
function queueCard(o,st){return `<article class="queue-card state-${queueState(o,st)}"><a class="queue-main" href="#order/${o.id}/${st.tab}"><span class="queue-cover">${o.cover_id?`<img src="/media/${o.cover_id}/thumb" alt="" loading="lazy" decoding="async">`:svgIcon(STAGE_ICONS[o.stage],28)}<span class="queue-status">${svgIcon(st.icon,18)}</span></span>${queueText(o,st)}</a>${actionButton(o,st,st.kind==='done'?'is-ready':'')}</article>`;}
// The shell stays put while polling redraws only the items, so the search field keeps focus.
function queuePage(key){const [k,label,color,ink,hint]=stageOf(key),n=STAGES.findIndex(s=>s[0]===k)+1,view=queueView();if($('.queue')?.dataset.stage===k){drawQueue(k);return;}state.queueQuery='';$('#main').innerHTML=`<div class="page queue" data-stage="${k}" style="--stage:${color};--stage-ink:${ink}"><span class="stage-chip">${svgIcon(STAGE_ICONS[k],14)}Этап ${n} из ${STAGES.length}</span><div class="queue-head"><h1>${label}</h1><div class="queue-tools"><label class="queue-search"><button type="button" data-v2="queue-search" title="Поиск" aria-label="Поиск">${svgIcon('search',16)}</button><input id="queue-search" type="search" placeholder="Школа или класс" aria-label="Поиск заказа"></label><div class="segmented" role="group" aria-label="Вид"><button data-v2="queue-view" data-view="list" aria-pressed="${view==='list'}" title="Список">${svgIcon('list',16)}</button><button data-v2="queue-view" data-view="grid" aria-pressed="${view==='grid'}" title="Плитка">${svgIcon('grid',16)}</button></div></div></div><p class="muted queue-hint">${hint}</p><div id="queue-items"></div></div>`;const input=$('#queue-search');input.oninput=()=>{state.queueQuery=input.value;drawQueue(k);};input.onblur=()=>{if(!input.value)input.parentElement.classList.remove('open');};input.onkeydown=e=>{if(e.key==='Escape'){input.value='';input.blur();state.queueQuery='';drawQueue(k);}};drawQueue(k);}
function drawQueue(k){const el=$('#queue-items');if(!el)return;const view=queueView(),q=(state.queueQuery||'').trim().toLowerCase(),all=state.orders.filter(o=>o.stage===k),rows=all.filter(o=>orderName(o).toLowerCase().includes(q)).map(o=>[o,cardStatus(o)]).sort((a,b)=>isMine(b[1])-isMine(a[1])||daysIn(b[0])-daysIn(a[0]));el.className='queue-'+view;el.innerHTML=rows.map(([o,st])=>(view==='grid'?queueCard:queueRow)(o,st)).join('')||(all.length?`<div class="empty-state"><h3>Ничего не найдено</h3><p>Нет заказов по запросу «${esc(state.queueQuery.trim())}».</p></div>`:`<div class="empty-state"><h3>Здесь пусто</h3><p>На этапе «${stageLabel(k)}» сейчас нет заказов.</p></div>`);}
function orderPage(){const o=state.order,s=stats(o);$('#main').innerHTML=`<div class="page"><div class="eyebrow"><a href="#home">Главная</a> / <a href="#stage/${o.stage}">${stageLabel(o.stage)}</a></div><div class="page-heading"><div><h1>${esc(orderName(o))}</h1><p class="muted">${count(o.copies,'альбом','альбома','альбомов')}</p></div><button class="secondary" data-v2="order-menu" data-id="${o.id}" aria-label="Действия с заказом">⋯</button></div><div id="order-status" aria-live="polite"></div><div class="workspace-tabs" role="navigation" aria-label="Разделы заказа">${[['photos','Фото',s.total],['persons','Персоны',o.persons.length],['client','Анкеты',''],['layout','Макет','']].map(([key,label,n])=>`<a href="#order/${o.id}/${key}" class="${state.view===key?'active':''}" ${state.view===key?'aria-current="page"':''}>${label}${n!==''?` <small>${n}</small>`:''}</a>`).join('')}</div><section id="workspace"></section></div>`;syncSummary(o);renderWorkspace();}
function renderGroups(){if(!$('#groups'))return;const o=state.order,unassigned=o.photos.filter(needsReview),pending=o.photos.filter(p=>['pending','processing'].includes(p.status)).length;$('#groups').innerHTML=`<div class="section-head"><h2>Персоны <span class="muted">${o.persons.length}</span></h2><div class="tabs"><button data-tab="persons" class="${state.tab==='persons'?'active':''}">По персонам</button><button data-tab="review" class="${state.tab==='review'?'active':''}">Проверить · ${unassigned.length}</button></div></div>${state.tab==='persons'?`<div class="person-grid">${o.persons.map((p,i)=>{const photos=o.photos.filter(f=>f.person_id===p.id);if(!photos.length)return '';return `<button class="person-card" data-person="${p.id}"><img src="/media/${photos[0].id}/thumb" alt="${esc(personName(p,i))}" loading="lazy" decoding="async">${photos.some(f=>f.uncertain)?'<span class="badge">Проверьте совпадение</span>':''}<div class="person-caption"><h3>${esc(personName(p,i))}</h3><p>${photoLabel(photos.length)}</p></div></button>`;}).join('')}</div>${!o.persons.length?`<div class="empty-state"><h3>${pending?'Ищем лица на фотографиях':'Персоны появятся здесь'}</h3><p>${pending?'Обработка идёт на компьютере. Можно продолжить загрузку.':unassigned.length?'Откройте «Проверить»: некоторым фотографиям нужна ваша помощь.':'Загрузите портреты — система соберёт снимки одного человека в группу.'}</p></div>`:''}`:`${gridTools()}${PhotoTools.reviewBoard(unassigned)}`}`;groupsSig=orderSignature(o);PhotoTools.changed();}
function photoTile(p,review=false){return `<label class="photo-tile"><img src="/media/${p.id}/thumb" alt="${esc(p.filename)}" loading="lazy" decoding="async"><input type="checkbox" data-photo="${p.id}" aria-label="Выбрать ${esc(p.filename)}" ${state.selected.has(p.id)?'checked':''}><button type="button" class="quick-view" data-review="view" data-id="${p.id}" title="Открыть крупно · Пробел" aria-label="Открыть ${esc(p.filename)} крупно">${svgIcon('eye',15)}</button><p title="${esc(p.filename)}">${esc(p.filename)}</p>${review?matchCaption(p):''}${review&&p.uncertain?'<small>Проверьте совпадение</small>':p.status!=='ready'?`<small>${statuses[p.status]||'Проверить'}</small>`:review?'<small class="photo-ready">Готово</small>':''}</label>`;}
function orderSignature(o){return JSON.stringify(o.shoots||[])+'|'+state.tab+'|'+o.persons.map(p=>p.id+':'+p.name).join(',')+'|'+o.photos.map(p=>[p.id,p.status,p.person_id||'',p.uncertain?1:0,p.error||'',p.filename].join(':')).join(';');}
function syncSummary(o){const el=$('#order-status');if(!el)return;const i=STAGES.findIndex(x=>x[0]===o.stage),step=stageStep(o),html=`<ol class="stage-line" aria-label="Этапы заказа">${STAGES.map(([k,l],n)=>`<li class="${n<i?'done':n===i?'current':''}" ${n===i?'aria-current="step"':''}>${l}</li>`).join('')}</ol>${o.client_progress?.enabled&&o.stage!=='forms'&&state.view==='client'?clientProgress(o):''}<div class="status-panel ${step.mine?'attention':'neutral'}"><div><span class="status-label">${esc(step.title)}</span>${step.text?`<p>${esc(step.text)}</p>`:''}${step.progress?`<progress max="${step.progress[1]}" value="${step.progress[0]}"></progress>`:''}</div><div class="step-actions">${step.actions||''}</div></div>`;if(el.renderedHtml!==html){el.innerHTML=html;el.renderedHtml=html;}}
function etaText(o){const sec=o.processing?.eta_seconds;return sec==null?'Оцениваем оставшееся время…':sec<60?'Осталось меньше минуты':`Осталось примерно ${Math.max(1,Math.floor(sec/60*.8))}–${Math.max(2,Math.ceil(sec/60*1.2))} мин`;}
function stageStep(o){const s=stats(o),c=o.client_progress,b=(v,label,cls='primary')=>`<button class="${cls}" data-v2="${v}">${label}</button>`,a=(tab,label,cls='secondary')=>state.view===tab?'':`<a class="${cls}" href="#order/${o.id}/${tab}">${label}</a>`,processing=s.pending?`Обработано ${s.total-s.pending} из ${s.total}. ${etaText(o)}`:'';switch(o.stage){case'new':return {title:'Загрузите первую съёмку',text:'Создайте съёмку, укажите дату и добавьте фотографии.',actions:b('add-photos','Загрузить фотографии'),mine:true};case'photos':return s.pending?{title:'Фотографии обрабатываются',text:processing,progress:[s.total-s.pending,s.total]}:{title:s.review?`${s.review} фото требуют проверки`:'Фотографии готовы',text:s.review?'Проверьте снимки или отправьте анкеты как есть.':'Проверьте персоны и отправьте классу анкеты для выбора портретов.',actions:s.review?a('review','Проверить','primary')+b('send-forms','Отправить как есть','secondary'):b('send-forms','Отправить на анкеты'),mine:true};case'forms':{const done=c?.status==='complete';return {title:done?'Все заполнили анкеты':'Класс заполняет анкеты',text:[c?.enabled?`Заполнено ${c.completed} из ${c.total}.`:'',processing].filter(Boolean).join(' '),progress:c?.enabled&&!done?[c.completed,c.total||1]:null,actions:a('client','Ссылка и коды')+b('make-layout','Создать макет'),mine:done};}case'layout':return {title:'Проверьте макет',text:'Когда макет готов, отправьте его классу на согласование.',actions:a('layout','Открыть макет')+b('publish-layout','Отправить на согласование'),mine:true};case'approval':return o.approved?{title:'Класс согласовал макет',text:'После отправки в печать макет больше не редактируется.',actions:b('allow-production','Отправить в печать'),mine:true}:{title:'Макет у класса',text:'Ждём согласования ответственного. Если нужно поправить макет, измените его и отправьте заново.',actions:a('layout','Открыть макет')+b('publish-layout','Отправить заново','secondary')+b('force-production','В печать без согласования','secondary')};case'print':return {title:'В печати',text:'Файлы для печати — во вкладке «Анкеты», в разделе «Заказ класса».',actions:b('stage-delivery','Передано в доставку')};case'delivery':return {title:'Доставка',actions:b('stage-archive','Перенести в архив')};default:return {title:'В архиве',actions:b('stage-delivery','Вернуть в доставку','secondary')};}}
function confirmStep(title,text,label,run){state.confirmRun=run;$('#action-content').innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button class="close" data-close="action-dialog" aria-label="Закрыть">×</button></div><p class="muted">${esc(text)}</p><p id="step-error" class="error" role="alert"></p><div class="dialog-actions"><button class="secondary" data-close="action-dialog">Отмена</button><button class="primary" data-v2="confirm-step">${esc(label)}</button></div>`;if(!$('#action-dialog').open)$('#action-dialog').showModal();}
function startOrderPolling(){clearInterval(pollTimer);pollTimer=setInterval(()=>{if(document.hidden)return;refreshOrder().catch(e=>{toast('Не удалось обновить обработку: '+e.message);});},5000);}
function renderProgress(){globalThis.PhotoTools?.renderPill();const el=$('#upload-status');if(!el)return;const p=state.progress;if(!p||p.orderId!==state.order?.id){el.innerHTML='';return;}el.innerHTML=`<progress max="${p.total}" value="${p.done}"></progress><strong>${state.uploading?'Загружаем':'Загрузка завершена'}: принято ${p.done-p.duplicates-p.errors.length} из ${p.total}</strong><p class="small muted">${p.duplicates?'Уже загружены: '+p.duplicates+' · ':''}Не загружено: ${p.errors.length}${state.uploading?' · Осталось: '+(p.total-p.done):''}</p>${p.errors.length?`<details class="upload-error"><summary>Показать ошибки (${p.errors.length})</summary>${p.errors.map(esc).join('<br>')}</details>`:''}`;}
// Files added during an upload join the same queue, so the photographer can keep dropping folders.
async function uploadFiles(files){if(!files.length)return;const orderId=state.order.id,shootId=state.shootId,shoot=state.order.shoots.find(s=>s.id===shootId);if(!shoot){openShootDialog(files);return;}if(state.uploading&&state.progress?.orderId!==orderId){toast('Дождитесь загрузки в другой заказ');return;}const allowed=f=>{const type=(f.type||'').toLowerCase();const name=f.name.toLowerCase();return ['image/jpeg','image/jpg','image/pjpeg','image/png','image/x-png'].includes(type)||/\.(jpe?g|png)$/.test(name);};if(!state.uploading)state.progress={orderId,total:0,done:0,duplicates:0,errors:[],kinds:new Set()};state.progress.total+=files.length;state.progress.kinds.add(shoot.kind);state.uploadQueue=(state.uploadQueue||[]).concat(files.map(file=>({file,shootId})));renderProgress();if(state.uploading)return;state.uploading=true;startOrderPolling();const worker=async()=>{while(state.uploadQueue.length){const {file,shootId}=state.uploadQueue.shift();try{if(!allowed(file))throw Error('Нужен файл JPG, JPEG или PNG');if(file.size>30*1024*1024)throw Error('Файл больше 30 МБ');const r=await api(`/orders/${orderId}/photos?shoot_id=${encodeURIComponent(shootId)}&filename=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});if(r.duplicate)state.progress.duplicates++;}catch(e){state.progress.errors.push(file.name+': '+e.message);}state.progress.done++;renderProgress();}};do{await Promise.all(Array.from({length:6},()=>worker()));}while(state.uploadQueue.length);state.uploading=false;state.progress.finishedAt=Date.now();renderProgress();toast(state.progress.errors.length?'Загрузка завершена с ошибками — проверьте список':state.progress.kinds.has('portrait')?'Фотографии загружены. Группируем по персонам.':'Фотографии добавлены в съёмку.');if(state.order?.id===orderId){await refreshOrder();startOrderPolling();}}
function showPerson(id){const o=state.order,index=o.persons.findIndex(p=>p.id===id),person=o.persons[index];if(!person)return;state.person=id;state.selected.clear();const photos=o.photos.filter(p=>p.person_id===id);$('#person-content').innerHTML=`<div class="dialog-heading"><h2 id="person-title">${esc(personName(person,index))}</h2><button class="close" data-close="person-dialog" aria-label="Закрыть">×</button></div><form id="name-form" class="name-form"><input name="name" placeholder="Имя и фамилия" aria-label="Имя персоны" maxlength="100" value="${esc(person.name)}"><button class="secondary" type="submit">Сохранить имя</button></form><p class="muted small">${photoLabel(photos.length)}. Выберите снимки, чтобы перенести их в другую группу или выделить в новую персону.</p>${gridTools()}<div class="photo-grid">${photos.map(p=>photoTile(p)).join('')}</div>`;$('#name-form').onsubmit=async e=>{e.preventDefault();try{await api(`/orders/${o.id}/persons/${id}`,json('PATCH',{name:new FormData(e.target).get('name')}));await refreshOrder();const name=state.order.persons.find(p=>p.id===id)?.name;$('#person-title').textContent=name||personName(person,index);toast('Имя сохранено');}catch(e){toast(e.message);}};if(!$('#person-dialog').open)$('#person-dialog').showModal();PhotoTools.changed();}
function openMove(){if(!state.selected.size){toast('Сначала выберите фотографии');return;}showPersonPicker({order:state.order,selected:[...state.selected],api,esc,personName});$('#move-dialog').showModal();}
async function refreshOrder(){const id=state.order?.id;if(!id)return;const fresh=withStage(await api('/orders/'+id));if(state.order?.id!==id)return;const previous=state.order;state.order=fresh;state.selected=new Set([...state.selected].filter(id=>fresh.photos.some(p=>p.id===id)));if(orderSignature(previous)!==orderSignature(fresh)){if(state.view==='persons')renderGroups();else if(state.view==='photos')renderWorkspace();document.querySelectorAll('.workspace-tabs a').forEach(a=>{if(a.href.endsWith('/photos'))a.innerHTML=`Фото <small>${fresh.photos.length}</small>`;if(a.href.endsWith('/persons'))a.innerHTML=`Персоны <small>${fresh.persons.length}</small>`;});}syncSummary(fresh);if(previous.stage!==fresh.stage&&state.view==='client')loadMvpDeal();PhotoTools.changed();if($('#client-fill-progress'))$('#client-fill-progress').innerHTML=clientProgress(fresh,true);}
async function route(){const version=++routeVersion;clearInterval(pollTimer);pollTimer=null;document.body.classList.remove('layout-mode');state.selected.clear();state.person=null;globalThis.PhotoTools?.changed();let hash=location.hash.slice(1)||'home';const params=new URLSearchParams(hash.split('?')[1]||'');hash=hash.split('?')[0];const legacy={photos:'stage/new',client:'stage/forms',layout:'stage/layout',ready:'stage/approval',print:'stage/print',delivery:'stage/delivery',archive:'stage/archive'};if(hash.startsWith('orders/'))hash='stage/'+hash.slice(7);if(legacy[hash])hash=legacy[hash];if(location.hash.slice(1).split('?')[0]!==hash)history.replaceState(null,'','#'+hash);try{state.orders=(await api('/orders')).map(withStage);if(version!==routeVersion)return;if(hash.startsWith('order/')){const [,id,view='photos']=hash.split('/');const order=withStage(await api('/orders/'+encodeURIComponent(id)));if(version!==routeVersion)return;if(state.order?.id!==order.id){state.shootId=undefined;state.clientLink=null;}state.order=order;state.view=['photos','persons','client','layout','review'].includes(view)?view:'photos';state.photoFilter=view==='review'?'review':'all';if(state.view==='review'){state.view='photos';state.shootId=undefined;}orderPage();if(state.view==='layout')loadLayout();startOrderPolling();const pending=state.pendingAction;state.pendingAction=null;if(pending?.id===order.id)$(`#order-status [data-v2="${pending.action}"]`)?.click();}else{state.order=null;const stage=hash.startsWith('stage/')?stageOf(hash.slice(6))[0]:null;const draw=()=>stage?queuePage(stage):hash==='orders'?drawOrders():hash==='home-classic'?drawClassicHome():drawHome();if(hash==='settings')await renderSettings();else if(hash==='schools')schoolsPage();else if(hash==='masters')await mastersPage();else if(stage)queuePage(stage);else if(hash==='orders')ordersPage(params);else if(hash==='home-classic')classicHomePage();else homePage();pollTimer=setInterval(async()=>{if(document.hidden||state.order)return;try{const fresh=(await api('/orders')).map(withStage);if(version!==routeVersion)return;if(JSON.stringify(fresh)!==JSON.stringify(state.orders)){state.orders=fresh;nav();if(!['settings','schools','masters'].includes(hash))draw();}}catch(error){toast('Не удалось обновить заказы: '+error.message);}},5000);}nav();}catch(e){$('#main').innerHTML=`<div class="page"><h1>Не удалось открыть страницу</h1><p class="error">${esc(e.message)}</p><a href="#home" class="secondary">На главную</a></div>`;}}
function needsReview(p){return p.shoot_type!=='general'&&!['pending','processing'].includes(p.status)&&(p.status!=='ready'||p.uncertain||!p.person_id);}
function stats(o){const photos=o.photos;return {total:photos?photos.length:o.photo_count||0,pending:photos?photos.filter(p=>['pending','processing'].includes(p.status)).length:o.pending||0,review:photos?photos.filter(needsReview).length:o.review_count||0};}
const ICONS={chevron:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',upload:'<path d="M12 15V3m-5 5 5-5 5 5M5 21h14"/>',loader:'<path d="M21 12a9 9 0 1 1-6.2-8.56"/>',alert:'<circle cx="12" cy="12" r="9"/><path d="M12 8v5m0 3h.01"/>',check:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',layout:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M12 4v16M3 12h9"/>',send:'<path d="m22 2-7 20-4-9-9-4z"/><path d="M22 2 11 13"/>',print:'<path d="M6 9V3h12v6M6 17H4V9h16v8h-2"/><rect x="6" y="14" width="12" height="7"/>',truck:'<path d="M3 6h11v10H3zM14 10h4l3 3v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="17" cy="18" r="2"/>',archive:'<rect x="3" y="4" width="18" height="4" rx="1"/><path d="M5 8v12h14V8M10 12h4"/>',photo:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="9" cy="10" r="2"/><path d="m21 16-5-5-8 8"/>',forms:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v3H9zM9 12h6M9 16h4"/>',approve:'<path d="M12 3l7 3v5c0 5-3 8-7 10-4-2-7-5-7-10V6z"/><path d="m9 12 2 2 4-4"/>',home:'<path d="M3 11l9-8 9 8v9a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>',templates:'<path d="m12 3 9 5-9 5-9-5z"/><path d="m3 13 9 5 9-5"/><path d="m3 17 9 5 9-5"/>',school:'<path d="M3 21h18M5 21V10l7-5 7 5v11"/><path d="M10 21v-5h4v5M12 10h.01"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',copy:'<rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v1"/>',trash:'<path d="M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14M10 11v6M14 11v6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>'};
const STAGE_ICONS={new:'upload',photos:'photo',forms:'forms',layout:'layout',approval:'approve',print:'print',delivery:'truck',archive:'archive'};
const svgIcon=(name,size=14)=>`<svg class="ico ico-${name}" viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]}</svg>`;
function cardStatus(o){const s=stats(o),c=o.client_progress;switch(o.stage){case'new':return {text:'Съёмка не загружена',kind:'todo',icon:'upload',tab:'photos',action:['add-photos','Загрузить фото']};case'photos':return s.pending?{text:`Обработка ${Math.round((s.total-s.pending)/s.total*100)}%`,kind:'working',icon:'loader',progress:[s.total-s.pending,s.total],tab:'photos'}:s.review?{text:`Проверить ${s.review} фото`,kind:'todo',icon:'alert',tab:'review',action:['review','Проверить фото']}:{text:'Фото готовы',kind:'done',icon:'check',tab:'photos',action:['send-forms','Отправить анкеты']};case'forms':return c?.status==='complete'?{text:'Все заполнили',kind:'done',icon:'check',tab:'client',action:['make-layout','Создать макет']}:{text:c?.enabled&&c.total?`Заполнили ${c.completed} из ${c.total}`:'Ждём класс',kind:'waiting',icon:'clock',progress:c?.enabled&&c.total?[c.completed,c.total]:null,tab:'client'};case'layout':return {text:'Макет готов к проверке',kind:'todo',icon:'layout',tab:'layout',action:['layout','Открыть макет']};case'approval':return o.approved?{text:'Согласовано',kind:'done',icon:'check',tab:'layout',action:['allow-production','Отправить в печать']}:{text:'Ждём согласования',kind:'waiting',icon:'clock',tab:'layout'};case'print':return {text:'В печати',kind:'working',icon:'print',tab:'client',action:['stage-delivery','Передано в доставку']};case'delivery':return {text:'В доставке',kind:'working',icon:'truck',tab:'client',action:['stage-archive','В архив']};default:return {text:'В архиве',kind:'waiting',icon:'archive',tab:'client'};}}
function nav(){const hash=location.hash.slice(1)||'home',active=state.order?'stage/'+state.order.stage:hash.split('?')[0]==='home-classic'?'home':hash.split('?')[0];const link=(href,key,inner)=>`<a href="${href}" class="${active===key?'active':''}" ${active===key?'aria-current="page"':''}>${inner}</a>`;$('#v2-nav').innerHTML=link('#home','home',`${svgIcon('home',18)}<span>Главная</span>`)+link('#orders','orders',`${svgIcon('list',18)}<span>Все заказы</span>` )+'<div class="nav-caption">Этапы</div>'+STAGES.map(([k,l,color])=>{const list=state.orders.filter(o=>o.stage===k),mine=list.filter(o=>isMine(cardStatus(o))).length;return link('#stage/'+k,'stage/'+k,`${svgIcon(STAGE_ICONS[k],18)}<span>${l}</span>${mine?`<small class="nav-mine" title="Ждут вас">${mine}</small>`:list.length?`<small>${list.length}</small>`:''}`);}).join('')+'<div class="nav-sep"></div>'+link('#masters','masters',`${svgIcon('templates',18)}<span>Мастер-макеты</span>`)+link('#schools','schools',`${svgIcon('school',18)}<span>Каталог школ</span><small>Скоро</small>`);}
function closeDesignMenus(){document.querySelectorAll('.design-menu.open').forEach(m=>{m.classList.remove('open');m.querySelector('.design-menu-list').hidden=true;m.querySelector('.design-menu-toggle').setAttribute('aria-expanded','false');});}
document.addEventListener('click',e=>{if(!e.target.closest('.design-menu'))closeDesignMenus();});
