async function mastersPage(){const version=routeVersion;$('#main').innerHTML='<div class="page"><div class="page-heading"><div><h1>Мастер-макеты</h1><p class="muted">Один визуальный стиль — столько комплектаций, сколько нужно.</p></div><button class="primary" data-v2="new-design">＋ Новый дизайн</button></div><div id="catalog" class="design-grid" aria-live="polite"><p class="muted">Загружаем дизайны…</p></div></div>';try{state.designs=await api('/designs');}catch(error){if(version===routeVersion)$('#catalog').innerHTML=`<p class="error">${esc(error.message)}</p>`;return;}if(version!==routeVersion)return;$('#catalog').innerHTML=state.designs.map((d,i)=>`<article class="design-card"><div class="design-cover cover-${i%3}"><div class="design-menu"><button type="button" class="design-menu-toggle" data-v2="design-menu" aria-haspopup="menu" aria-expanded="false" aria-label="Действия с дизайном">${svgIcon('more',18)}</button><div class="design-menu-list" role="menu" hidden><button type="button" role="menuitem" data-v2="duplicate-design" data-id="${d.id}">${svgIcon('copy',16)}Дублировать</button><button type="button" role="menuitem" class="danger" data-v2="delete-design" data-id="${d.id}">${svgIcon('trash',16)}Удалить</button></div></div><div class="cover-book"><div><small>ALBUM<br>FACTORY</small><strong>${esc(d.name)}</strong><span>Выпускной альбом</span></div><div class="cover-art"><i></i><i></i><i></i></div></div></div><div class="design-card-content"><div class="card-heading"><h2>${esc(d.name)}</h2></div><div class="package-list">${d.packages.map(p=>`<a href="/static/master-editor.html?id=${encodeURIComponent(p.template_id)}"><span><strong>${esc(p.name)}</strong></span><span>${p.price.toLocaleString('ru-RU')} ₽ <b>↗</b></span></a>`).join('')}</div><button class="add-package" data-v2="new-package" data-id="${d.id}">＋ Новая комплектация</button></div></article>`).join('')||'<div class="empty-card"><h2>Здесь будут ваши дизайны</h2><p>Создайте первый дизайн и его комплектацию. Стартовые развороты уже подготовлены.</p></div>';}
function schoolsPage(){$('#main').innerHTML='<div class="page"><h1>Каталог школ</h1><p class="muted queue-hint">Школы, классы и учителя в одном месте: чтобы не вводить их заново в каждом заказе.</p><div class="empty-state"><h3>Раздел в разработке</h3><p>Скоро здесь появится справочник школ и учителей.</p></div></div>';}
